import { ReactNode, useContext, useEffect, useState } from "react";
import { createContext } from "react";
import {
  TodosContextLoading,
  TodosContextType,
  TodosToServer,
} from "../models/Todo";
import { todosService } from "../services/todos.service";
import { useAppNavigate } from "../hooks/useAppNavigate";
import { CreateAndUpateFormType } from "../models/CreateAndUpdateFromTypes";
import { useLocation } from "react-router-dom";
import localStorageService from "../services/localStorage.service";

export const TodosContext = createContext<TodosContextType | undefined>(
  undefined
);

interface TodosProviderProps {
  children: ReactNode;
}

export const TodosProvider = ({ children }: TodosProviderProps) => {
  const [todos, setTodos] = useState<TodosToServer[] | undefined>([]);
  const [todo, setTodo] = useState<TodosToServer | undefined>();
  const [isLoading, setIsLoading] = useState<TodosContextLoading>({
    createForm: false,
    editForm: false,
    deleteItem: false,
    getItems: false,
    getItem: false,
    favouriteItem: false,
    isDoneItem: false,
    removeItem: false,
  });

  const appNavigate = useAppNavigate();

  const location = useLocation();

  const currentUser = localStorageService.getLocalUserId();

  useEffect(() => {
    if (currentUser) {
      getTodos();
    }
  }, [currentUser]);

  const getTodos = async () => {
    try {
      setIsLoading((prev) => ({ ...prev, getItems: true }));
      const data = await todosService.get<TodosToServer[]>(currentUser!);
      setTodos(data);
    } catch (error) {
      console.log(error);
    } finally {
      setIsLoading((prev) => ({ ...prev, getItems: false }));
    }
  };

  const getTodoById = async (id: string) => {
    try {
      setIsLoading((prev) => ({ ...prev, getItem: true }));
      const data = await todosService.getById<TodosToServer>(id, currentUser!);
      setTodo(data);
    } catch (error) {
      console.log(error);
    } finally {
      setIsLoading((prev) => ({ ...prev, getItem: false }));
    }
  };

  const createUpdateTodos = async (
    payload: TodosToServer,
    loadingType: keyof TodosContextLoading,
    mode?: CreateAndUpateFormType,
    redirect?: boolean
  ) => {
    try {
      if (mode && mode === "create") {
        setIsLoading((prev) => ({ ...prev, createForm: true }));
      } else if (mode && (mode === "edit" || mode === "edit-item")) {
        setIsLoading((prev) => ({
          ...prev,
          [loadingType]: { id: payload.id! },
        }));
      }

      const data = await todosService.createAndUpdate<TodosToServer>(
        payload!,
        currentUser!
      );

      if (mode && mode === "create") {
        setTodos((prev) => (prev ? [...prev, data] : [data]));
      } else if (mode && (mode === "edit" || mode === "edit-item")) {
        setTodos(
          (prev) =>
            prev && prev.map((item) => (item.id === data.id ? data : item))
        );

        if (mode === "edit-item") {
          setTodo(payload);
        }
      }

      if (redirect) {
        appNavigate(location.state?.from || "/todos");
      }
    } catch (error) {
      console.log(error);
    } finally {
      setIsLoading((prev) => ({ ...prev, [loadingType]: false }));
    }
  };

  const deleteTodos = async (id: string, redirect?: boolean) => {
    try {
      setIsLoading((prev) => ({ ...prev, deleteItem: { id } }));

      const data = await todosService.delete(id, currentUser!);
      if (data === null) {
        setTodos((prev) => prev && prev.filter((todo) => todo.id !== id));

        if (redirect) {
          appNavigate("/todos");
        }
      }
    } catch (error) {
      console.log(error);
    } finally {
      setIsLoading((prev) => ({ ...prev, deleteItem: false }));
    }
  };

  const resetTodo = () => {
    setTodo(undefined);
  };

  return (
    <TodosContext.Provider
      value={{
        todos,
        todo,
        isLoading,
        getTodos,
        createUpdateTodos,
        deleteTodos,
        getTodoById,
        resetTodo,
      }}
    >
      {children}
    </TodosContext.Provider>
  );
};
